  "chunk_id": "exec-10-1",
  "command": "perl -e '
open(F,"<:raw","/app/data.txt");{local $/;$d=<F>;} @b=unpack("C*",$d); $n=scalar(@b);
sub cost_int { my($v,$t0)=@_; my $S=$v+(1<<$t0); my $tmp=0; my $x=$S; while($x>1){$x>>=1;$tmp++} # tmp = floor(log2 S) ? check: S=16 -> 10000, floor log2=4, tmp=4 correct
  # above loop: count shifts until 1
  my $k=$tmp-$t0; return ($k+1)+$tmp; }
# test
print cost_int(0,4)," ",cost_int(15,4)," ",cost_int(16,4),"\n";
# estimate greedy
$pos=0; $tokens=0; $bits=0;
# j cost later
@tokens=();
while($pos<$n){
  $best_len=0; $best_off=0;
  $maxlen=$n-$pos; $maxlen=500 if $maxlen>500;
  $start=$pos-4868; $start=0 if $start<0;
  for($s=$start;$s<$pos;$s++){
    # quick filter first char
    next if $b[$s]!=$b[$pos];
    $l=0; while($l<$maxlen && $b[$s+$l]==$b[$pos+$l]){$l++}
    if($l>$best_len){$best_len=$l;$best_off=$pos-$s-1}
  }
  if($best_len>=3){
    # match cost: flag 1 + off + len
    $c=1+cost_int($best_off,5)+cost_int($best_len-1,2);
    # literal cost for same bytes if done as literals: sum
    $lit=0; for($k=0;$k<$best_len;$k++){ $S=($b[$pos+$k]<128?$b[$pos+$k]:$b[$pos+$k]-256); $m=abs($S); $lit+=1+1+cost_int($m,4); }
    if($c < $lit){ push @tokens,["M",$best_off,$best_len]; $bits+=$c; $pos+=$best_len; $tokens++; next; }
  }
  # literal
  $S=($b[$pos]<128?$b[$pos]:$b[$pos]-256); $m=abs($S);
  $bits+=1+1+cost_int($m,4); push @tokens,["L",$b[$pos]]; $pos++; $tokens++;
}
# j cost
$jc=cost_int($tokens+1,9); # +1 for terminator? terminator literal cost too
print "tokens $tokens bits $bits +j $jc total ".($bits+$jc)."\n";
$bytes=($bits+$jc)/8; print "est bytes $bytes\n";
# add terminator literal 0: cost 1+1+cost_int(0,4)=1+1+5=7
print "with term: ".($bits+$jc+7).", bytes ".(($bits+$jc+7)/8)."\n";
'",
